10: import "@openzeppelin/contracts/security/Pausable.sol";
11: import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
12: 
13: /**
14:  * @title  PatientFundParticipatoryBudgeting
15:  * @author Pharmacy Fiduciary Commons
16:  * @notice Governs the allocation of the Patient Fund matching pool using squared vote weights.
17:  *         Credential-gated voting enables community members to vote on local health projects.
18:  */
19: contract PatientFundParticipatoryBudgeting is AccessControl, EIP712, Pausable, ReentrancyGuard {
20:     using SafeERC20 for IERC20;
21:     using ECDSA for bytes32;
22: 
23:     bytes32 public constant COUNCIL_ROLE = keccak256("COUNCIL_ROLE");
24:     bytes32 public constant GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");
25:     uint256 public constant MAX_PROJECTS_PER_ROUND = 50;
26:     uint256 public constant MAX_VOTERS_PER_BATCH = 200;
27:     uint256 public constant MATCH_RECLAIM_GRACE_PERIOD = 90 days;
28:     bytes32 public constant REGISTRATION_TYPEHASH = keccak256(
29:         "VoterRegistration(uint256 roundId,address voter,uint256 nonce,bytes32 credentialHash,bytes32 policyVersion,uint256 deadline)"
30:     );
31:     bytes32 public constant CREDENTIAL_TYPEHASH = keccak256(
32:         "VoterCredential(uint256 roundId,address voter,uint256 nonce,bytes32 credentialHash,bytes32 policyVersion,uint256 deadline)"
33:     );
34:     bytes32 public constant ACCEPTED_CREDENTIAL_POLICY_VERSION = keccak256(
35:         "fiduciary-credential-policy-v1"
36:     );
37:     bytes32 public constant MOCK_ZK_PROOF_DOMAIN = keccak256(
38:         "fiduciary-mock-zk-proof-v1"
39:     );
40:     bytes32 public constant MOCK_ZK_VERIFIER_VERSION = keccak256(
41:         "fiduciary-mock-zk-verifier-v1"
42:     );
43:     bytes32 public constant MOCK_ZK_REGISTRATION_TYPEHASH = keccak256(
44:         "MockZKRegistration(uint256 roundId,address voter,bytes32 nullifier,bytes32 verifierVersion,bytes32 root)"
45:     );
46: 
47:     enum RoundState { Inactive, Active, Finalized }
48: 
49:     struct Project {
50:         string title;
51:         address recipient;
52:         uint256 voteCount;
53:         bool active;
54:     }
55: 
56:     struct ProjectProposal {
57:         string title;
58:         address recipient;
59:         uint256 supportCount;
60:         bool registered;
61:     }
62: 
63:     struct Round {
64:         uint256 matchingPool;
65:         RoundState state;
66:         uint256 projectCount;
67:         uint256 finalizedAt;
68:         uint256 freshMatchingPool;
69:         bool isZKMode;
70:     }
71: 
72:     IERC20 public immutable token;
73:     address public immutable council;
74:     uint256 public currentRound;
75:     address public relayerVerifier;
76:     address public mockZKVerifier;
77:     uint256 public recycledMatchingPool;
78:     uint256 public totalUnclaimedShares;
79:     uint256 public totalDebt;
80: 
81:     // roundId -> Round details
82:     mapping(uint256 => Round) public rounds;
83:     
84:     // roundId => projectId => Project details
85:     mapping(uint256 => mapping(uint256 => Project)) public roundProjects;
86:     
87:     // roundId => voter => isRegistered
88:     mapping(uint256 => mapping(address => bool)) public registeredVoters;
89:     
90:     // roundId => voter => projectId => hasVoted
91:     mapping(uint256 => mapping(address => mapping(uint256 => bool))) public hasVoted;
92: 
93:     // roundId => voter => next relayer authorization nonce
94:     mapping(uint256 => mapping(address => uint256)) public registrationNonces;
95: 
96:     // roundId => nullifier => consumed in mock ZK-mode registration
97:     mapping(uint256 => mapping(bytes32 => bool)) public roundNullifiersUsed;
98: 
99:     // roundId => mock credential membership root accepted for ZK-mode registration
100:     mapping(uint256 => bytes32) public roundMockZKRoots;
101: 
102:     // roundId => projectId => matching share amount
103:     mapping(uint256 => mapping(uint256 => uint256)) public roundProjectShares;
104: 
105:     // roundId => cumulative solvency shortfall first observed during round actions
106:     mapping(uint256 => uint256) public roundDeficit;
107: 
108:     // issuerAddress => isTrusted
109:     mapping(address => bool) public trustedCredentialIssuers;
110: 
111:     uint256 public projectSupportThreshold = 3;
112: 
113:     // roundId => proposalId => ProjectProposal details
114:     mapping(uint256 => mapping(uint256 => ProjectProposal)) public roundProposals;
115:     // roundId => proposalCount
116:     mapping(uint256 => uint256) public roundProposalCount;
117:     // roundId => proposalId => voter => hasSupported
118:     mapping(uint256 => mapping(uint256 => mapping(address => bool))) public hasSupportedProposal;
119: 
120:     // =========================================================
121:     // EVENTS
122:     // ====================================================
